data: {"index":1,"delta":{"text":" is a sophisticated software tool that translates human-readable source code, written in a high-level","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" programming language like C++, Rust, or Java, into low-level machine code that a computer’s processor can execute directly. This translation","type":"text"},"event_type":"step.delta"}

