data: {"index":1,"delta":{"text":"`), identifiers (`variableName`), operators (`+`, `-`), and literals (`42`, `\"hello\"`). \n","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":"During this process, the lexer also strips away elements that are irrelevant to the computer, such as whitespace, formatting, and comments. If","type":"text"},"event_type":"step.delta"}

