data: {"index":1,"delta":{"text":" the lexer encounters an invalid character sequence (like an illegal symbol), it throws a lexical error.\n\n### 2","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":". Syntax Analysis (Parsing)\nOnce the code is broken into tokens, it passes to the syntax analyzer, or \"parser.\" The","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" parser checks the linear sequence of tokens against the formal grammatical rules of the programming language. \nIf the structure is valid","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":", the parser builds a hierarchical, tree-like data structure called a **Parse Tree** or **Abstract Syntax Tree (AST","type":"text"},"event_type":"step.delta"}

