data: {"index":1,"delta":{"text":" bogged down by extraneous punctuation like parentheses or semicolons. If the code violates the grammar rules (e.g., missing a semicolon or","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" a mismatched parenthesis), the parser halts and reports a syntax error.\n\n### 3. Semantic Analysis\nHaving established that the code *","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":"looks* correct grammatically, the compiler must ensure it *makes sense* logically. This is the role of the semantic analyzer. ","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":"\nDuring this stage, the compiler traverses the AST to check for semantic rules. It maintains a **symbol table** to track","type":"text"},"event_type":"step.delta"}

