data: {"index":1,"delta":{"text":"C, Swift, Go) that all output the same IR, which can then feed into a unified optimization and code-generation pipeline. ","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":"\n\n### 5. Code Optimization\nThe middle-end of the compiler takes the IR and attempts to make it run","type":"text"},"event_type":"step.delta"}

