data: {"index":1,"delta":{"text":" faster, use less memory, or both, without changing the program's observable output. This is often an iterative process involving","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" numerous optimization passes.\nCommon optimizations include **dead code elimination** (removing code that is never executed), **loop un","type":"text"},"event_type":"step.delta"}

